  isPrime(2) && isPrime(3) && isPrime(7) && isPrime(97),
  "2/3/7/97 应为质数"
);
console.assert(
  isPrime(4) === false && isPrime(100) === false && isPrime(91) === false,
  "4/100/91(=7×13) 应为合数"
);
