lru.put("c", 30);
console.assert(lru.get("c") === 30, "重复 put 应更新值");
console.assert(
  JSON.stringify(lru.keysFromOldest()) === '["a","d","c"]',
  "热度顺序应为 a->d->c"
);
console.assert(lru.get("未命中") === void 0, "未命中应返回 undefined");
const tiny = new LRUCache(1);
tiny.put(1, "一");
tiny.put(2, "二");
console.assert(
  tiny.get(1) === void 0 && tiny.get(2) === "二",
